import { useMemo, useState } from "react";
import { toast } from "sonner";
import {
  Activity, AlertTriangle, ArrowRight, Banknote, CalendarDays, CheckCircle2,
  ChevronRight, CircleDollarSign, ClipboardCheck, CreditCard, FileCheck,
  Landmark, Loader2, Phone, Plus, ReceiptText, RefreshCw, Save, ShieldCheck,
  TrendingUp, Users, Wallet, X,
} from "lucide-react";
import { trpc } from "../lib/trpc";
import { CreditScoringSettingsDialog, EscalationGovernancePanel, EscalationSettingsDialog } from "./MicrofinanceGovernanceDialogs";

const currency = new Intl.NumberFormat("en-TZ", { style: "currency", currency: "TZS", currencyDisplay: "code", maximumFractionDigits: 0 });
const tabs = [
  ["overview", "Portfolio", TrendingUp], ["borrowers", "Borrowers & KYC", Users], ["credit", "Credit desk", ClipboardCheck],
  ["portfolio", "Repayments", ReceiptText], ["savings", "Savings & cash", Wallet], ["collections", "Collections", AlertTriangle], ["governance", "Governance", ShieldCheck],
];

function tzToday() {
  const parts = new Intl.DateTimeFormat("en-CA", { timeZone: "Africa/Dar_es_Salaam", year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(new Date());
  const value = Object.fromEntries(parts.map((part) => [part.type, part.value]));
  return `${value.year}-${value.month}-${value.day}`;
}
function errorMessage(error, fallback = "The operation could not be completed.") { return error?.message || fallback; }
function StatCard({ label, value, detail, tone = "emerald", icon: Icon }) {
  const colors = { emerald: "bg-emerald-50 text-emerald-700", blue: "bg-blue-50 text-blue-700", amber: "bg-amber-50 text-amber-700", rose: "bg-rose-50 text-rose-700", violet: "bg-violet-50 text-violet-700" };
  return <article className="sm-panel sm-panel-interactive rounded-2xl p-4"><div className="flex items-start justify-between gap-3"><div><p className="text-[11px] font-semibold uppercase tracking-[.12em] text-slate-500">{label}</p><p className="mt-2 text-xl font-bold tracking-tight text-slate-950">{value}</p><p className="mt-1 text-xs text-slate-500">{detail}</p></div><div className={`rounded-xl p-2.5 ${colors[tone]}`}><Icon size={18}/></div></div></article>;
}
function Badge({ children, tone = "slate" }) { const classes = { slate: "bg-slate-100 text-slate-700", emerald: "bg-emerald-100 text-emerald-700", blue: "bg-blue-100 text-blue-700", amber: "bg-amber-100 text-amber-800", rose: "bg-rose-100 text-rose-700", violet: "bg-violet-100 text-violet-700" }; return <span className={`inline-flex rounded-full px-2 py-0.5 text-[11px] font-semibold ${classes[tone] || classes.slate}`}>{children}</span>; }
function statusTone(status = "") { const label = String(status).toLowerCase(); if (label.includes("approved") || label.includes("active") || label.includes("paid") || label.includes("verified") || label.includes("closed") || label.includes("deposit")) return "emerald"; if (label.includes("submitted") || label.includes("due") || label.includes("partial") || label.includes("open") || label.includes("pending")) return "amber"; if (label.includes("overdue") || label.includes("rejected") || label.includes("variance")) return "rose"; if (label.includes("disbursed")) return "blue"; return "slate"; }
function Button({ children, className = "", variant = "primary", type = "button", ...props }) { const styles = { primary: "bg-emerald-700 text-white hover:bg-emerald-800", outline: "border border-slate-300 bg-white text-slate-700 hover:bg-slate-50", danger: "bg-rose-600 text-white hover:bg-rose-700", subtle: "bg-emerald-50 text-emerald-800 hover:bg-emerald-100" }; return <button type={type} className={`inline-flex min-h-11 items-center justify-center gap-2 rounded-xl px-3.5 text-sm font-semibold transition active:scale-[.98] disabled:cursor-not-allowed disabled:opacity-50 aria-busy:cursor-wait aria-busy:pointer-events-none focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-600/40 ${styles[variant]} ${className}`} {...props}>{children}</button>; }
function Field({ label, children, hint }) { return <label className="block text-sm font-medium text-slate-700"><span>{label}</span>{children}<span className="mt-1 block text-xs text-slate-500">{hint}</span></label>; }
function Input({ className = "", ...props }) { return <input className={`mt-1.5 min-h-11 w-full rounded-xl border border-slate-300 bg-white px-3 text-sm text-slate-900 outline-none transition placeholder:text-slate-400 focus:border-emerald-600 focus:ring-2 focus:ring-emerald-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-600/40 ${className}`} {...props}/>; }
function Select({ children, ...props }) { return <select className="mt-1.5 min-h-11 w-full rounded-xl border border-slate-300 bg-white px-3 text-sm text-slate-900 outline-none focus:border-emerald-600 focus:ring-2 focus:ring-emerald-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-600/40" {...props}>{children}</select>; }
function EmptyState({ title, description, action }) { return <div className="rounded-2xl border border-dashed border-slate-300 bg-slate-50 px-5 py-10 text-center"><div className="mx-auto mb-3 flex h-11 w-11 items-center justify-center rounded-2xl bg-white text-emerald-700 shadow-sm"><Landmark size={20}/></div><h3 className="font-semibold text-slate-900">{title}</h3><p className="mx-auto mt-1 max-w-md text-sm text-slate-500">{description}</p>{action && <div className="mt-4">{action}</div>}</div>; }
function Panel({ title, subtitle, action, children, className = "" }) { return <section className={`sm-panel rounded-2xl ${className}`}><div className="flex flex-wrap items-start justify-between gap-3 border-b border-slate-100 px-4 py-4"><div><h2 className="font-semibold text-slate-950">{title}</h2>{subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}</div>{action}</div>{children}</section>; }
function Modal({ open, title, description, onClose, children }) { if (!open) return null; return <div role="dialog" aria-modal="true" aria-labelledby="mfi-modal-title" aria-describedby="mfi-modal-description" className="fixed inset-0 z-[70] flex items-end bg-slate-950/45 p-0 sm:items-center sm:justify-center sm:p-5"><div className="max-h-[92vh] w-full overflow-y-auto rounded-t-3xl bg-white shadow-2xl sm:max-w-2xl sm:rounded-3xl"><div className="sticky top-0 z-10 flex items-start justify-between gap-3 border-b border-slate-100 bg-white px-5 py-4"><div><h2 id="mfi-modal-title" className="font-semibold text-slate-950">{title}</h2><p id="mfi-modal-description" className="mt-1 text-sm text-slate-500">{description}</p></div><button type="button" aria-label="Close dialog" onClick={onClose} className="min-h-11 min-w-11 rounded-lg p-2 text-slate-500 hover:bg-slate-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-600/40"><X size={18}/></button></div><div className="p-5">{children}</div></div></div>; }
function InlineError({ error }) { return error ? <div role="alert" className="rounded-xl border border-rose-200 bg-rose-50 px-3 py-2.5 text-sm text-rose-700">{error}</div> : null; }

export function MicrofinanceWorkspace() {
  const [tab, setTab] = useState("overview");
  const [dialog, setDialog] = useState(null);
  const [selectedApplication, setSelectedApplication] = useState(null);
  const [selectedLoan, setSelectedLoan] = useState(null);
  const [selectedBorrower, setSelectedBorrower] = useState(null);
  const [selectedSession, setSelectedSession] = useState(null);
  const input = useMemo(() => ({ limit: 200 }), []);
  const utils = trpc.useUtils();
  const query = trpc.microfinance.dashboard.useQuery(input, { retry: false, refetchOnWindowFocus: false });
  const audit = trpc.microfinance.auditHistory.useQuery(input, { enabled: tab === "governance", retry: false });
  const scoring = trpc.microfinance.creditScoringSettings.useQuery(undefined, { enabled: tab === "credit" || tab === "governance", retry: false });
  const escalation = trpc.microfinance.escalationSettings.useQuery(undefined, { enabled: tab === "governance", retry: false });
  const escalationHistory = trpc.microfinance.escalationHistory.useQuery(input, { enabled: tab === "governance", retry: false });
  const refresh = async () => { await utils.microfinance.dashboard.invalidate(); if (tab === "governance") { await Promise.all([utils.microfinance.auditHistory.invalidate(), utils.microfinance.escalationSettings.invalidate(), utils.microfinance.escalationHistory.invalidate()]); } if (tab === "credit") await utils.microfinance.creditScoringSettings.invalidate(); };
  const data = query.data;
  const mutateOptions = (message, close = true) => ({ onSuccess: async () => { toast.success(message); if (close) setDialog(null); await refresh(); }, onError: (error) => toast.error(errorMessage(error)) });
  const createBorrower = trpc.microfinance.createBorrower.useMutation(mutateOptions("Borrower and KYC record saved"));
  const createGroup = trpc.microfinance.createGroup.useMutation(mutateOptions("Borrower group created"));
  const createProduct = trpc.microfinance.createLoanProduct.useMutation(mutateOptions("Loan product activated"));
  const createGuarantor = trpc.microfinance.createGuarantor.useMutation(mutateOptions("Guarantor recorded"));
  const createCollateral = trpc.microfinance.createCollateral.useMutation(mutateOptions("Collateral recorded"));
  const submitApplication = trpc.microfinance.submitApplication.useMutation(mutateOptions("Loan application submitted for credit review"));
  const decideApplication = trpc.microfinance.decideApplication.useMutation(mutateOptions("Credit decision recorded"));
  const disburse = trpc.microfinance.disburseLoan.useMutation(mutateOptions("Loan disbursed and repayment schedule created"));
  const repayment = trpc.microfinance.recordRepayment.useMutation({ ...mutateOptions("Repayment posted and receipt issued"), onSuccess: async (result) => { toast.success(`Repayment posted · ${result.receiptNumber}`); setDialog(null); await refresh(); } });
  const savings = trpc.microfinance.recordSavings.useMutation(mutateOptions("Savings transaction posted"));
  const openCash = trpc.microfinance.openCashSession.useMutation(mutateOptions("Cash session opened"));
  const closeCash = trpc.microfinance.closeCashSession.useMutation(mutateOptions("Cash session closed"));
  const collection = trpc.microfinance.createCollectionAction.useMutation(mutateOptions("Collection action assigned"));
  const saveScoring = trpc.microfinance.saveCreditScoringSettings.useMutation(mutateOptions("Credit scoring rules saved"));
  const saveEscalation = trpc.microfinance.saveEscalationSettings.useMutation(mutateOptions("Daily escalation configuration saved"));
  const busy = createBorrower.isPending || createGroup.isPending || createProduct.isPending || submitApplication.isPending || decideApplication.isPending || disburse.isPending || repayment.isPending || savings.isPending || openCash.isPending || closeCash.isPending || collection.isPending || createGuarantor.isPending || createCollateral.isPending || saveScoring.isPending || saveEscalation.isPending;
  const openCashSession = data?.cashSessions?.find((item) => item.status === "Open");

  if (query.isLoading) return <div className="space-y-4 animate-pulse"><div className="h-36 rounded-3xl bg-emerald-100"/><div className="grid grid-cols-2 gap-3 lg:grid-cols-4">{Array.from({ length: 4 }).map((_, index) => <div key={index} className="h-28 rounded-2xl bg-slate-100"/>)}</div></div>;
  if (query.error) return <div className="rounded-3xl border border-rose-200 bg-rose-50 p-6"><AlertTriangle className="text-rose-600"/><h1 className="mt-3 text-lg font-bold text-rose-950">Microfinance data is unavailable</h1><p className="mt-1 max-w-lg text-sm text-rose-700">{errorMessage(query.error, "The secure microfinance service could not load this workspace.")}</p><Button className="mt-4" onClick={() => query.refetch()}><RefreshCw size={16}/>Retry securely</Button></div>;
  const permissions = data?.permissions || {};
  return <div className="space-y-4 pb-8">
    <header className="overflow-hidden rounded-3xl bg-[linear-gradient(120deg,#064e3b_0%,#047857_56%,#0f766e_100%)] px-5 py-5 text-white shadow-sm sm:px-6"><div className="flex flex-wrap items-start justify-between gap-4"><div><div className="mb-2 flex items-center gap-2 text-xs font-semibold uppercase tracking-[.16em] text-emerald-100"><Landmark size={14}/>Tanzania-ready lending operations</div><h1 className="text-2xl font-bold tracking-tight">Microfinance Command Center</h1><p className="mt-1 max-w-2xl text-sm text-emerald-50">Borrowers, credit controls, cash, repayments, savings, collections, audit evidence, and portfolio quality in one tenant-safe workspace.</p></div><div className="flex flex-wrap gap-2"><Button variant="subtle" onClick={() => setDialog("borrower")}><Plus size={16}/>Borrower</Button><Button className="bg-white text-emerald-800 hover:bg-emerald-50" onClick={() => setDialog("application")} disabled={!data?.borrowers?.length || !data?.products?.length}><FileCheck size={16}/>Loan application</Button></div></div><div className="mt-5 flex flex-wrap gap-2 text-xs text-emerald-50"><span className="rounded-full border border-white/20 bg-white/10 px-2.5 py-1">TZS ledger</span><span className="rounded-full border border-white/20 bg-white/10 px-2.5 py-1">Africa/Dar_es_Salaam dates</span><span className="rounded-full border border-white/20 bg-white/10 px-2.5 py-1">Mobile-money-ready boundary</span></div></header>
    <nav aria-label="Microfinance sections" className="flex gap-1 overflow-x-auto rounded-2xl border border-slate-200 bg-white p-1 shadow-sm">{tabs.map(([id, label, Icon]) => <button key={id} onClick={() => setTab(id)} className={`flex shrink-0 items-center gap-2 rounded-xl px-3 py-2.5 text-sm font-semibold transition ${tab === id ? "bg-emerald-700 text-white shadow-sm" : "text-slate-600 hover:bg-slate-50"}`}><Icon size={15}/>{label}</button>)}</nav>
    {tab === "overview" && <Overview data={data} onAction={setDialog} onNavigate={setTab}/>}
    {tab === "borrowers" && <BorrowersTab data={data} onAction={setDialog} onSelectBorrower={setSelectedBorrower} permissions={permissions}/>} 
    {tab === "credit" && <CreditTab data={data} scoring={scoring} onAction={setDialog} onDecision={setSelectedApplication} permissions={permissions}/>} 
    {tab === "portfolio" && <PortfolioTab data={data} onRepay={setSelectedLoan} onDisburse={setSelectedApplication} permissions={permissions}/>} 
    {tab === "savings" && <SavingsCashTab data={data} onAction={setDialog} onCloseSession={setSelectedSession} permissions={permissions}/>} 
    {tab === "collections" && <CollectionsTab data={data} onAction={setSelectedLoan} permissions={permissions}/>} 
    {tab === "governance" && <><GovernanceTab data={data} audit={audit} onRefresh={refresh} permissions={permissions}/><EscalationGovernancePanel scoring={scoring} escalation={escalation} history={escalationHistory} scorecards={data?.scorecards || []} onConfigureScoring={() => setDialog("credit-scoring")} onConfigureEscalation={() => setDialog("par-escalation")}/></>} 
    <BorrowerDialog open={dialog === "borrower"} onClose={() => setDialog(null)} mutation={createBorrower} groups={data?.groups || []} busy={busy}/>
    <GroupDialog open={dialog === "group"} onClose={() => setDialog(null)} mutation={createGroup} busy={busy}/>
    <ProductDialog open={dialog === "product"} onClose={() => setDialog(null)} mutation={createProduct} busy={busy}/>
    <GuarantorDialog open={dialog === "guarantor"} onClose={() => setDialog(null)} mutation={createGuarantor} borrowers={data?.borrowers || []} selectedBorrower={selectedBorrower} busy={busy}/>
    <CollateralDialog open={dialog === "collateral"} onClose={() => setDialog(null)} mutation={createCollateral} borrowers={data?.borrowers || []} selectedBorrower={selectedBorrower} busy={busy}/>
    <ApplicationDialog open={dialog === "application"} onClose={() => setDialog(null)} mutation={submitApplication} borrowers={data?.borrowers || []} products={data?.products || []} groups={data?.groups || []} busy={busy}/>
    <DecisionDialog application={selectedApplication} onClose={() => setSelectedApplication(null)} mutation={decideApplication} busy={busy}/>
    <DisbursementDialog application={selectedApplication?.status === "Approved" ? selectedApplication : null} onClose={() => setSelectedApplication(null)} mutation={disburse} sessions={data?.cashSessions || []} busy={busy}/>
    <RepaymentDialog loan={selectedLoan?.status === "Active" || selectedLoan?.status === "Overdue" ? selectedLoan : null} onClose={() => setSelectedLoan(null)} mutation={repayment} sessions={data?.cashSessions || []} busy={busy}/>
    <CollectionDialog loan={tab === "collections" ? selectedLoan : null} onClose={() => setSelectedLoan(null)} mutation={collection} busy={busy}/>
    <SavingsDialog open={dialog === "savings"} onClose={() => setDialog(null)} mutation={savings} borrowers={data?.borrowers || []} sessions={data?.cashSessions || []} busy={busy}/>
    <CashOpenDialog open={dialog === "cash-open"} onClose={() => setDialog(null)} mutation={openCash} busy={busy}/>
    <CashCloseDialog session={selectedSession} onClose={() => setSelectedSession(null)} mutation={closeCash} busy={busy}/>
    <CreditScoringSettingsDialog open={dialog === "credit-scoring"} onClose={() => setDialog(null)} mutation={saveScoring} settings={scoring.data?.settings} busy={busy}/>
    <EscalationSettingsDialog open={dialog === "par-escalation"} onClose={() => setDialog(null)} mutation={saveEscalation} settings={escalation.data?.settings} busy={busy}/>
  </div>;
}

function Overview({ data, onAction, onNavigate }) { const { metrics } = data; return <div className="space-y-4"><div className="grid grid-cols-2 gap-3 lg:grid-cols-4"><StatCard label="Outstanding portfolio" value={currency.format(metrics.portfolioOutstanding)} detail={`${metrics.activeLoanCount} active loans`} tone="blue" icon={CircleDollarSign}/><StatCard label="PAR 30" value={`${metrics.par30Ratio.toFixed(1)}%`} detail={currency.format(metrics.par30Amount)} tone={metrics.par30Ratio > 5 ? "rose" : "emerald"} icon={AlertTriangle}/><StatCard label="Savings balance" value={currency.format(metrics.savingsBalance)} detail="Confirmed deposits less withdrawals" tone="violet" icon={Wallet}/><StatCard label="Collections posted" value={currency.format(metrics.repaymentCollected)} detail="Recorded repayment receipts" tone="emerald" icon={ReceiptText}/></div><div className="grid gap-4 lg:grid-cols-3"><Panel title="Operational queue" subtitle="Actions that protect portfolio quality" className="lg:col-span-2"><div className="divide-y divide-slate-100">{[{ title: "Credit applications awaiting decision", description: `${data.applications.filter((item) => item.status === "Submitted").length} submitted applications need a credit decision.`, button: "Open credit desk", action: () => onNavigate("credit") }, { title: "Overdue scheduled installments", description: `${data.schedules.filter((item) => item.daysPastDue > 0).length} installments are past due and need collection follow-up.`, button: "Open collections", action: () => onNavigate("collections") }, { title: "Cash control", description: data.cashSessions.some((item) => item.status === "Open") ? "An open teller cash session is available for cash-backed postings." : "Open a cash session before processing cash transactions.", button: data.cashSessions.some((item) => item.status === "Open") ? "View cash" : "Open session", action: () => data.cashSessions.some((item) => item.status === "Open") ? onNavigate("savings") : onAction("cash-open") }].map((item) => <div key={item.title} className="flex flex-wrap items-center justify-between gap-3 px-4 py-4"><div><h3 className="font-semibold text-slate-900">{item.title}</h3><p className="mt-1 text-sm text-slate-500">{item.description}</p></div><Button variant="outline" onClick={item.action}>{item.button}<ChevronRight size={15}/></Button></div>)}</div></Panel><Panel title="Portfolio profile" subtitle="Real-time status from posted records"><div className="space-y-3 p-4"><div className="rounded-xl bg-emerald-50 p-3"><p className="text-xs font-semibold uppercase tracking-wide text-emerald-700">KYC verification</p><p className="mt-1 text-xl font-bold text-emerald-950">{data.metrics.verifiedBorrowerCount} / {data.metrics.borrowerCount}</p><p className="text-xs text-emerald-700">Borrowers marked verified</p></div><div className="rounded-xl bg-slate-50 p-3"><p className="text-xs font-semibold uppercase tracking-wide text-slate-600">Active product catalogue</p><p className="mt-1 text-xl font-bold text-slate-950">{data.products.filter((item) => item.status === "Active").length}</p><p className="text-xs text-slate-500">Configured lending products</p></div></div></Panel></div></div>; }
function BorrowersTab({ data, onAction, onSelectBorrower }) { const [search, setSearch] = useState(""); const borrowers = data.borrowers.filter((item) => `${item.name} ${item.phone} ${item.village}`.toLowerCase().includes(search.toLowerCase())); return <div className="space-y-4"><Panel title="Borrowers & KYC" subtitle="Secure borrower registry, identity status, group membership, guarantors, and collateral." action={<div className="flex flex-wrap gap-2"><Button variant="outline" onClick={() => onAction("group")}><Users size={15}/>Group</Button><Button onClick={() => onAction("borrower")}><Plus size={15}/>Borrower</Button></div>}><div className="border-b border-slate-100 p-4"><Input aria-label="Search borrowers" placeholder="Search name, phone or village" value={search} onChange={(event) => setSearch(event.target.value)}/></div>{borrowers.length ? <div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left text-sm"><thead className="bg-slate-50 text-xs uppercase tracking-wide text-slate-500"><tr><th className="px-4 py-3">Borrower</th><th className="px-4 py-3">KYC</th><th className="px-4 py-3">Location</th><th className="px-4 py-3">Group</th><th className="px-4 py-3">Status</th><th className="px-4 py-3">Actions</th></tr></thead><tbody>{borrowers.map((item) => <tr key={item.id} className="border-t border-slate-100"><td className="px-4 py-3"><p className="font-semibold text-slate-900">{item.name}</p><p className="mt-0.5 flex items-center gap-1 text-xs text-slate-500"><Phone size={11}/>{item.phone}</p></td><td className="px-4 py-3"><Badge tone={statusTone(item.kycStatus)}>{item.kycStatus}</Badge></td><td className="px-4 py-3 text-slate-600">{item.village}, {item.district}</td><td className="px-4 py-3 text-slate-600">{data.groups.find((group) => group.id === item.groupId)?.name || "Individual"}</td><td className="px-4 py-3"><Badge tone={statusTone(item.status)}>{item.status}</Badge></td><td className="px-4 py-3"><div className="flex gap-2"><button onClick={() => { onSelectBorrower(item); onAction("guarantor"); }} className="text-xs font-semibold text-emerald-700 hover:underline">Guarantor</button><button onClick={() => { onSelectBorrower(item); onAction("collateral"); }} className="text-xs font-semibold text-emerald-700 hover:underline">Collateral</button></div></td></tr>)}</tbody></table></div> : <EmptyState title="No borrowers match this view" description="Register a borrower with required KYC fields before starting a loan application." action={<Button onClick={() => onAction("borrower")}><Plus size={15}/>Register borrower</Button>}/>}</Panel><Panel title="Borrower groups" subtitle="Group structures for solidarity lending and meeting tracking.">{data.groups.length ? <div className="grid gap-3 p-4 md:grid-cols-2 xl:grid-cols-3">{data.groups.map((group) => <div key={group.id} className="rounded-xl border border-slate-200 p-3"><div className="flex items-start justify-between"><div><h3 className="font-semibold text-slate-900">{group.name}</h3><p className="mt-1 text-sm text-slate-500">{group.meetingDay || "Meeting day pending"}</p></div><Badge tone={statusTone(group.status)}>{group.status}</Badge></div><p className="mt-3 text-xs text-slate-500">{group.memberCount} recorded members</p></div>)}</div> : <div className="p-4"><EmptyState title="No groups created" description="Create groups for group-loan and community lending operations." action={<Button variant="outline" onClick={() => onAction("group")}>Create group</Button>}/></div>}</Panel></div>; }
function CreditTab({ data, scoring, onAction, onDecision }) { const rules = scoring.data?.settings; return <div className="space-y-4"><Panel title="Credit scoring controls" subtitle="Each submitted application receives an immutable scorecard using the approved tenant rule set." action={scoring.data?.canManage ? <Button variant="outline" onClick={() => onAction("credit-scoring")}><ShieldCheck size={15}/>Configure rules</Button> : null}><div className="grid gap-3 p-4 sm:grid-cols-3"><div className="rounded-xl bg-emerald-50 p-3"><p className="text-xs font-semibold uppercase tracking-wide text-emerald-700">Approval threshold</p><p className="mt-1 text-xl font-bold text-emerald-950">{rules?.approvalThreshold ?? "—"} points</p></div><div className="rounded-xl bg-amber-50 p-3"><p className="text-xs font-semibold uppercase tracking-wide text-amber-700">Manual review</p><p className="mt-1 text-xl font-bold text-amber-950">{rules?.reviewThreshold ?? "—"} points</p></div><div className="rounded-xl bg-slate-50 p-3"><p className="text-xs font-semibold uppercase tracking-wide text-slate-600">Max debt service</p><p className="mt-1 text-xl font-bold text-slate-950">{rules?.maxDebtServiceRatio ?? "—"}%</p></div></div></Panel><Panel title="Loan products" subtitle="Controlled pricing, terms, fees, penalties, and security requirements." action={<Button onClick={() => onAction("product")}><Plus size={15}/>Loan product</Button>}>{data.products.length ? <div className="grid gap-3 p-4 md:grid-cols-2 xl:grid-cols-3">{data.products.map((item) => <div key={item.id} className="rounded-2xl border border-slate-200 p-4"><div className="flex items-start justify-between"><div><h3 className="font-semibold text-slate-900">{item.name}</h3><p className="mt-1 text-xs font-semibold tracking-wide text-emerald-700">{item.code}</p></div><Badge tone={statusTone(item.status)}>{item.status}</Badge></div><dl className="mt-4 grid grid-cols-2 gap-x-3 gap-y-2 text-sm"><div><dt className="text-xs text-slate-500">Principal range</dt><dd className="font-semibold text-slate-800">{currency.format(item.minimumPrincipal)} – {currency.format(item.maximumPrincipal)}</dd></div><div><dt className="text-xs text-slate-500">Annual interest</dt><dd className="font-semibold text-slate-800">{item.annualInterestRate}%</dd></div><div><dt className="text-xs text-slate-500">Repayment</dt><dd className="font-semibold capitalize text-slate-800">{item.repaymentFrequency}</dd></div><div><dt className="text-xs text-slate-500">Penalty / month</dt><dd className="font-semibold text-slate-800">{item.penaltyRateMonthly}%</dd></div></dl></div>)}</div> : <div className="p-4"><EmptyState title="No loan products are active" description="Create a product with controlled price and term limits before accepting applications." action={<Button onClick={() => onAction("product")}><Plus size={15}/>Create product</Button>}/></div>}</Panel><Panel title="Credit decision queue" subtitle="Submitted applications require an authorized approval or rejection decision." action={<Button onClick={() => onAction("application")} disabled={!data.borrowers.length || !data.products.length}><FileCheck size={15}/>New application</Button>}>{data.applications.length ? <div className="overflow-x-auto"><table className="w-full min-w-[900px] text-left text-sm"><thead className="bg-slate-50 text-xs uppercase tracking-wide text-slate-500"><tr><th className="px-4 py-3">Applicant</th><th className="px-4 py-3">Product</th><th className="px-4 py-3">Requested</th><th className="px-4 py-3">Scorecard</th><th className="px-4 py-3">KYC</th><th className="px-4 py-3">Status</th><th className="px-4 py-3">Action</th></tr></thead><tbody>{data.applications.map((item) => <tr key={item.id} className="border-t border-slate-100"><td className="px-4 py-3 font-semibold text-slate-900">{item.borrowerName}</td><td className="px-4 py-3 text-slate-600">{item.productName}</td><td className="px-4 py-3 font-semibold text-slate-900">{currency.format(item.amount)}</td><td className="px-4 py-3"><p className="font-semibold text-slate-900">{item.creditScore ?? "—"}</p><p className="text-xs text-slate-500">{item.creditRecommendation || "Awaiting score"}</p></td><td className="px-4 py-3"><Badge tone={statusTone(item.kycStatus)}>{item.kycStatus || "Pending"}</Badge></td><td className="px-4 py-3"><Badge tone={statusTone(item.status)}>{item.status}</Badge></td><td className="px-4 py-3">{item.status === "Submitted" ? <button onClick={() => onDecision(item)} className="text-xs font-semibold text-emerald-700 hover:underline">Decide</button> : item.status === "Approved" ? <button onClick={() => onDecision(item)} className="text-xs font-semibold text-emerald-700 hover:underline">Disburse</button> : <span className="text-xs text-slate-400">No action</span>}</td></tr>)}</tbody></table></div> : <div className="p-4"><EmptyState title="No loan applications" description="Once borrower KYC and a loan product are ready, submit a controlled loan request for review."/></div>}</Panel></div>; }
function PortfolioTab({ data, onRepay, onDisburse }) { return <div className="space-y-4"><Panel title="Active loan book" subtitle="Disbursed loans, outstanding balance, repayment channel, and mobile-money evidence.">{data.loans.length ? <div className="overflow-x-auto"><table className="w-full min-w-[930px] text-left text-sm"><thead className="bg-slate-50 text-xs uppercase tracking-wide text-slate-500"><tr><th className="px-4 py-3">Loan</th><th className="px-4 py-3">Borrower</th><th className="px-4 py-3">Principal</th><th className="px-4 py-3">Outstanding</th><th className="px-4 py-3">Disbursed</th><th className="px-4 py-3">Channel</th><th className="px-4 py-3">Status</th><th className="px-4 py-3"></th></tr></thead><tbody>{data.loans.map((loan) => <tr key={loan.id} className="border-t border-slate-100"><td className="px-4 py-3"><p className="font-mono text-xs font-semibold text-emerald-800">{loan.number}</p><p className="mt-1 text-xs text-slate-500">{loan.productName}</p></td><td className="px-4 py-3 font-semibold text-slate-900">{loan.borrowerName}</td><td className="px-4 py-3 text-slate-700">{currency.format(loan.principal)}</td><td className="px-4 py-3 font-semibold text-slate-950">{currency.format(loan.outstanding)}</td><td className="px-4 py-3 text-slate-600">{loan.disbursedOn}</td><td className="px-4 py-3"><p className="capitalize text-slate-700">{loan.paymentMethod || "—"}</p>{loan.mobileMoneyState !== "Not applicable" && <p className="mt-1 max-w-[180px] text-xs text-amber-700">{loan.mobileMoneyState}</p>}</td><td className="px-4 py-3"><Badge tone={statusTone(loan.status)}>{loan.status}</Badge></td><td className="px-4 py-3">{["Active", "Overdue"].includes(loan.status) ? <button onClick={() => onRepay(loan)} className="text-xs font-semibold text-emerald-700 hover:underline">Record repayment</button> : null}</td></tr>)}</tbody></table></div> : <EmptyState title="No disbursed loans" description="Approved applications can be disbursed by authorized cash or finance staff after the credit decision."/>}</Panel><Panel title="Repayment schedule & PAR" subtitle="Installment status is calculated from scheduled outstanding balance and Tanzania local dates.">{data.schedules.length ? <div className="overflow-x-auto"><table className="w-full min-w-[780px] text-left text-sm"><thead className="bg-slate-50 text-xs uppercase tracking-wide text-slate-500"><tr><th className="px-4 py-3">Loan</th><th className="px-4 py-3">Borrower</th><th className="px-4 py-3">Due date</th><th className="px-4 py-3">Outstanding</th><th className="px-4 py-3">Days past due</th><th className="px-4 py-3">Status</th></tr></thead><tbody>{data.schedules.map((item) => <tr key={item.id} className="border-t border-slate-100"><td className="px-4 py-3 font-mono text-xs text-emerald-800">{item.loanNumber}</td><td className="px-4 py-3 font-semibold text-slate-900">{item.borrowerName}</td><td className="px-4 py-3 text-slate-600">{item.dueDate}</td><td className="px-4 py-3 font-semibold text-slate-900">{currency.format(item.outstanding)}</td><td className="px-4 py-3"><span className={item.daysPastDue >= 30 ? "font-semibold text-rose-700" : "text-slate-600"}>{item.daysPastDue} days</span></td><td className="px-4 py-3"><Badge tone={statusTone(item.status)}>{item.status}</Badge></td></tr>)}</tbody></table></div> : <div className="p-4"><EmptyState title="No repayment schedules" description="A controlled schedule is created automatically only when an approved application is disbursed."/></div>}</Panel></div>; }
function SavingsCashTab({ data, onAction, onCloseSession }) { const open = data.cashSessions.find((item) => item.status === "Open"); return <div className="space-y-4"><div className="grid gap-4 lg:grid-cols-3"><Panel title="Teller cash control" subtitle="Open and close sessions with expected-balance reconciliation." className="lg:col-span-1" action={open ? null : <Button onClick={() => onAction("cash-open")}><Banknote size={15}/>Open cash</Button>}><div className="p-4">{open ? <div className="rounded-xl bg-emerald-50 p-4"><div className="flex items-center justify-between"><p className="font-semibold text-emerald-950">Open cash session</p><Badge tone="emerald">Open</Badge></div><p className="mt-2 text-sm text-emerald-800">Opening float: <strong>{currency.format(open.openingBalance)}</strong></p><p className="mt-1 text-xs text-emerald-700">{open.tellerName || "Current teller"} · opened {open.openedOn}</p><Button className="mt-4 w-full" variant="outline" onClick={() => onCloseSession(open)}>Close and reconcile</Button></div> : <EmptyState title="No cash session open" description="Cash entries require an open teller session."/>}</div></Panel><Panel title="Savings ledger" subtitle="Deposits and withdrawals are validated against each borrower’s recorded balance." className="lg:col-span-2" action={<Button onClick={() => onAction("savings")}><Plus size={15}/>Savings transaction</Button>}>{data.savings.length ? <div className="overflow-x-auto"><table className="w-full min-w-[670px] text-left text-sm"><thead className="bg-slate-50 text-xs uppercase tracking-wide text-slate-500"><tr><th className="px-4 py-3">Date</th><th className="px-4 py-3">Borrower</th><th className="px-4 py-3">Type</th><th className="px-4 py-3">Channel</th><th className="px-4 py-3">Amount</th></tr></thead><tbody>{data.savings.map((item) => <tr key={item.id} className="border-t border-slate-100"><td className="px-4 py-3 text-slate-600">{item.transactedOn}</td><td className="px-4 py-3 font-semibold text-slate-900">{item.borrowerName}</td><td className="px-4 py-3"><Badge tone={item.status === "Deposit" ? "emerald" : "rose"}>{item.status}</Badge></td><td className="px-4 py-3 capitalize text-slate-600">{item.paymentMethod}</td><td className="px-4 py-3 font-semibold text-slate-900">{item.status === "Deposit" ? "+" : "−"}{currency.format(item.amount)}</td></tr>)}</tbody></table></div> : <div className="p-4"><EmptyState title="No savings transactions" description="Record a validated deposit or withdrawal for an active borrower."/></div>}</Panel></div></div>; }
function CollectionsTab({ data, onAction }) { const overdue = data.schedules.filter((item) => item.daysPastDue > 0); return <div className="space-y-4"><Panel title="Overdue & PAR work queue" subtitle="Prioritize installments that are due or past due; record assignment, promise, visit, or restructure review.">{overdue.length ? <div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left text-sm"><thead className="bg-rose-50 text-xs uppercase tracking-wide text-rose-700"><tr><th className="px-4 py-3">Borrower</th><th className="px-4 py-3">Loan</th><th className="px-4 py-3">Due date</th><th className="px-4 py-3">Outstanding</th><th className="px-4 py-3">Days late</th><th className="px-4 py-3"></th></tr></thead><tbody>{overdue.map((item) => { const loan = data.loans.find((loanItem) => loanItem.id === item.loanId); return <tr key={item.id} className="border-t border-slate-100"><td className="px-4 py-3 font-semibold text-slate-900">{item.borrowerName}</td><td className="px-4 py-3 font-mono text-xs text-emerald-800">{item.loanNumber}</td><td className="px-4 py-3 text-slate-600">{item.dueDate}</td><td className="px-4 py-3 font-semibold text-rose-700">{currency.format(item.outstanding)}</td><td className="px-4 py-3"><Badge tone={item.daysPastDue >= 30 ? "rose" : "amber"}>{item.daysPastDue} days</Badge></td><td className="px-4 py-3">{loan && <button onClick={() => onAction(loan)} className="text-xs font-semibold text-emerald-700 hover:underline">Assign action</button>}</td></tr>; })}</tbody></table></div> : <EmptyState title="No overdue installments" description="Portfolio quality is clear on the current repayment schedule."/>}</Panel><Panel title="Collection action history" subtitle="Open actions are tenant-scoped and tied to a specific loan.">{data.collections.length ? <div className="divide-y divide-slate-100">{data.collections.map((item) => <div key={item.id} className="flex flex-wrap items-center justify-between gap-3 px-4 py-3"><div><p className="font-semibold text-slate-900">{item.action} · {item.borrowerName}</p><p className="mt-1 text-xs text-slate-500">Due {item.dueOn} · {item.assignedToName}</p></div><Badge tone={statusTone(item.status)}>{item.status}</Badge></div>)}</div> : <div className="p-4"><EmptyState title="No collection actions" description="Actions logged against overdue loans appear here for accountable follow-up."/></div>}</Panel></div>; }
function GovernanceTab({ data, audit, onRefresh }) { return <div className="space-y-4"><Panel title="Operational notifications" subtitle="System-generated alerts for applications, cash reconciliation, repayment completion, and workflow controls." action={<Button variant="outline" onClick={onRefresh}><RefreshCw size={15}/>Refresh</Button>}>{data.notifications.length ? <div className="divide-y divide-slate-100">{data.notifications.map((item) => <div key={item.id} className="flex gap-3 px-4 py-3"><div className={`mt-0.5 rounded-lg p-2 ${item.severity === "Critical" ? "bg-rose-100 text-rose-700" : item.severity === "Warning" ? "bg-amber-100 text-amber-700" : "bg-blue-100 text-blue-700"}`}><Activity size={15}/></div><div><p className="font-semibold text-slate-900">{item.name}</p><p className="mt-1 text-xs text-slate-500">{new Date(item.createdAt).toLocaleString("en-TZ", { timeZone: "Africa/Dar_es_Salaam" })}</p></div></div>)}</div> : <div className="p-4"><EmptyState title="No active notifications" description="Approval, cash-control, and repayment events will be visible here."/></div>}</Panel><Panel title="Microfinance audit history" subtitle="Protected action trail; financial record details are available only to authorized audit roles.">{audit.isLoading ? <div className="p-5 text-sm text-slate-500">Loading audit history…</div> : audit.error ? <div className="p-5 text-sm text-slate-500">Audit history is restricted to authorized audit or executive roles.</div> : audit.data?.rows?.length ? <div className="divide-y divide-slate-100">{audit.data.rows.map((item) => <div key={item.id} className="flex flex-wrap items-center justify-between gap-3 px-4 py-3"><div><p className="font-semibold text-slate-900">{item.action}</p><p className="mt-1 text-xs text-slate-500">{item.actorName || "System"} · {item.entityType}</p></div><time className="text-xs text-slate-500">{new Date(item.createdAt).toLocaleString("en-TZ", { timeZone: "Africa/Dar_es_Salaam" })}</time></div>)}</div> : <div className="p-4"><EmptyState title="No audit entries yet" description="Authorized microfinance actions create a tenant-scoped audit record."/></div>}</Panel></div>; }

function BorrowerDialog({ open, onClose, mutation, groups, busy }) { const [form, setForm] = useState({ firstName: "", lastName: "", phone: "", nationalId: "", dateOfBirth: "", gender: "Female", village: "", district: "", region: "", occupation: "", monthlyIncome: "", kycStatus: "Pending", groupId: "" }); const update = (key, value) => setForm((current) => ({ ...current, [key]: value })); const submit = (event) => { event.preventDefault(); mutation.mutate({ ...form, monthlyIncome: Number(form.monthlyIncome || 0), groupId: form.groupId || null }); }; return <Modal open={open} title="Register borrower" description="Capture core KYC and location information before credit operations." onClose={onClose}><form onSubmit={submit} className="space-y-4"><InlineError error={mutation.error?.message}/><div className="grid gap-3 sm:grid-cols-2"><Field label="First name"><Input required value={form.firstName} onChange={(e) => update("firstName", e.target.value)}/></Field><Field label="Last name"><Input required value={form.lastName} onChange={(e) => update("lastName", e.target.value)}/></Field><Field label="Mobile number"><Input required inputMode="tel" placeholder="07XX XXX XXX" value={form.phone} onChange={(e) => update("phone", e.target.value)}/></Field><Field label="National ID"><Input required value={form.nationalId} onChange={(e) => update("nationalId", e.target.value)}/></Field><Field label="Date of birth"><Input required type="date" value={form.dateOfBirth} onChange={(e) => update("dateOfBirth", e.target.value)}/></Field><Field label="Gender"><Select value={form.gender} onChange={(e) => update("gender", e.target.value)}><option>Female</option><option>Male</option><option>Other</option><option>Prefer not to say</option></Select></Field><Field label="Village / ward"><Input required value={form.village} onChange={(e) => update("village", e.target.value)}/></Field><Field label="District"><Input required value={form.district} onChange={(e) => update("district", e.target.value)}/></Field><Field label="Region"><Input required value={form.region} onChange={(e) => update("region", e.target.value)}/></Field><Field label="Occupation"><Input value={form.occupation} onChange={(e) => update("occupation", e.target.value)}/></Field><Field label="Monthly income (TZS)"><Input type="number" min="0" value={form.monthlyIncome} onChange={(e) => update("monthlyIncome", e.target.value)}/></Field><Field label="KYC status"><Select value={form.kycStatus} onChange={(e) => update("kycStatus", e.target.value)}><option>Pending</option><option>Verified</option><option>Needs review</option></Select></Field><Field label="Borrower group"><Select value={form.groupId} onChange={(e) => update("groupId", e.target.value)}><option value="">Individual borrower</option>{groups.map((group) => <option key={group.id} value={group.id}>{group.name}</option>)}</Select></Field></div><div className="flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Cancel</Button><Button type="submit" disabled={busy}>{busy && <Loader2 className="animate-spin" size={15}/>}Save borrower</Button></div></form></Modal>; }
function GroupDialog({ open, onClose, mutation, busy }) { const [form, setForm] = useState({ name: "", meetingDay: "", meetingLocation: "", chairperson: "" }); const submit = (event) => { event.preventDefault(); mutation.mutate(form); }; return <Modal open={open} title="Create borrower group" description="Create an accountable group record for solidarity lending." onClose={onClose}><form onSubmit={submit} className="space-y-4"><InlineError error={mutation.error?.message}/><Field label="Group name"><Input required value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })}/></Field><Field label="Meeting day"><Input required placeholder="e.g. Tuesday" value={form.meetingDay} onChange={(e) => setForm({ ...form, meetingDay: e.target.value })}/></Field><Field label="Meeting location"><Input required value={form.meetingLocation} onChange={(e) => setForm({ ...form, meetingLocation: e.target.value })}/></Field><Field label="Chairperson"><Input value={form.chairperson} onChange={(e) => setForm({ ...form, chairperson: e.target.value })}/></Field><div className="flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Cancel</Button><Button type="submit" disabled={busy}>Create group</Button></div></form></Modal>; }
function ProductDialog({ open, onClose, mutation, busy }) { const [form, setForm] = useState({ name: "", code: "", minimumPrincipal: "", maximumPrincipal: "", annualInterestRate: "", setupFeeRate: "0", insuranceFeeRate: "0", penaltyRateMonthly: "0", collectorCommissionRate: "0", termMinMonths: "1", termMaxMonths: "12", repaymentFrequency: "monthly", requiresGuarantor: false, requiresCollateral: false }); const update = (key, value) => setForm((current) => ({ ...current, [key]: value })); const submit = (event) => { event.preventDefault(); mutation.mutate({ ...form, code: form.code.toUpperCase(), minimumPrincipal: Number(form.minimumPrincipal), maximumPrincipal: Number(form.maximumPrincipal), annualInterestRate: Number(form.annualInterestRate), setupFeeRate: Number(form.setupFeeRate), insuranceFeeRate: Number(form.insuranceFeeRate), penaltyRateMonthly: Number(form.penaltyRateMonthly), collectorCommissionRate: Number(form.collectorCommissionRate), termMinMonths: Number(form.termMinMonths), termMaxMonths: Number(form.termMaxMonths) }); }; return <Modal open={open} title="Create loan product" description="Pricing is controlled server-side and applied only on approved disbursement." onClose={onClose}><form onSubmit={submit} className="space-y-4"><InlineError error={mutation.error?.message}/><div className="grid gap-3 sm:grid-cols-2"><Field label="Product name"><Input required value={form.name} onChange={(e) => update("name", e.target.value)}/></Field><Field label="Product code"><Input required value={form.code} onChange={(e) => update("code", e.target.value)}/></Field><Field label="Minimum principal (TZS)"><Input required type="number" min="1" value={form.minimumPrincipal} onChange={(e) => update("minimumPrincipal", e.target.value)}/></Field><Field label="Maximum principal (TZS)"><Input required type="number" min="1" value={form.maximumPrincipal} onChange={(e) => update("maximumPrincipal", e.target.value)}/></Field><Field label="Annual interest (%)"><Input required type="number" min="0" step="0.01" value={form.annualInterestRate} onChange={(e) => update("annualInterestRate", e.target.value)}/></Field><Field label="Setup fee (%)"><Input type="number" min="0" step="0.01" value={form.setupFeeRate} onChange={(e) => update("setupFeeRate", e.target.value)}/></Field><Field label="Insurance fee (%)"><Input type="number" min="0" step="0.01" value={form.insuranceFeeRate} onChange={(e) => update("insuranceFeeRate", e.target.value)}/></Field><Field label="Monthly penalty (%)"><Input type="number" min="0" step="0.01" value={form.penaltyRateMonthly} onChange={(e) => update("penaltyRateMonthly", e.target.value)}/></Field><Field label="Collector commission (%)"><Input type="number" min="0" step="0.01" value={form.collectorCommissionRate} onChange={(e) => update("collectorCommissionRate", e.target.value)}/></Field><Field label="Repayment frequency"><Select value={form.repaymentFrequency} onChange={(e) => update("repaymentFrequency", e.target.value)}><option value="weekly">Weekly</option><option value="biweekly">Biweekly</option><option value="monthly">Monthly</option></Select></Field><Field label="Minimum term (months)"><Input required type="number" min="1" value={form.termMinMonths} onChange={(e) => update("termMinMonths", e.target.value)}/></Field><Field label="Maximum term (months)"><Input required type="number" min="1" value={form.termMaxMonths} onChange={(e) => update("termMaxMonths", e.target.value)}/></Field></div><div className="flex flex-wrap gap-4 rounded-xl bg-slate-50 p-3 text-sm text-slate-700"><label className="flex items-center gap-2"><input type="checkbox" checked={form.requiresGuarantor} onChange={(e) => update("requiresGuarantor", e.target.checked)}/>Require guarantor</label><label className="flex items-center gap-2"><input type="checkbox" checked={form.requiresCollateral} onChange={(e) => update("requiresCollateral", e.target.checked)}/>Require collateral</label></div><div className="flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Cancel</Button><Button type="submit" disabled={busy}>Activate product</Button></div></form></Modal>; }
function GuarantorDialog({ open, onClose, mutation, borrowers, selectedBorrower, busy }) { const [form, setForm] = useState({ borrowerId: "", fullName: "", phone: "", nationalId: "", relationship: "", guaranteedAmount: "" }); const borrowerId = selectedBorrower?.id || form.borrowerId; const submit = (event) => { event.preventDefault(); mutation.mutate({ ...form, borrowerId, guaranteedAmount: Number(form.guaranteedAmount) }); }; return <Modal open={open} title="Record guarantor" description="Guarantor evidence is tied to a borrower and evaluated when submitting loan applications." onClose={onClose}><form onSubmit={submit} className="space-y-3"><InlineError error={mutation.error?.message}/>{!selectedBorrower && <Field label="Borrower"><Select required value={form.borrowerId} onChange={(e) => setForm({ ...form, borrowerId: e.target.value })}><option value="">Select borrower</option>{borrowers.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</Select></Field>}<Field label="Full name"><Input required value={form.fullName} onChange={(e) => setForm({ ...form, fullName: e.target.value })}/></Field><div className="grid gap-3 sm:grid-cols-2"><Field label="Phone"><Input required value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })}/></Field><Field label="National ID"><Input required value={form.nationalId} onChange={(e) => setForm({ ...form, nationalId: e.target.value })}/></Field><Field label="Relationship"><Input required value={form.relationship} onChange={(e) => setForm({ ...form, relationship: e.target.value })}/></Field><Field label="Guaranteed amount (TZS)"><Input required type="number" min="1" value={form.guaranteedAmount} onChange={(e) => setForm({ ...form, guaranteedAmount: e.target.value })}/></Field></div><div className="flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Cancel</Button><Button type="submit" disabled={busy}>Save guarantor</Button></div></form></Modal>; }
function CollateralDialog({ open, onClose, mutation, borrowers, selectedBorrower, busy }) { const [form, setForm] = useState({ borrowerId: "", description: "", collateralType: "", estimatedValue: "", documentReference: "" }); const borrowerId = selectedBorrower?.id || form.borrowerId; const submit = (event) => { event.preventDefault(); mutation.mutate({ ...form, borrowerId, estimatedValue: Number(form.estimatedValue) }); }; return <Modal open={open} title="Record collateral" description="Record a described asset and estimated value; the credit officer retains approval responsibility." onClose={onClose}><form onSubmit={submit} className="space-y-3"><InlineError error={mutation.error?.message}/>{!selectedBorrower && <Field label="Borrower"><Select required value={form.borrowerId} onChange={(e) => setForm({ ...form, borrowerId: e.target.value })}><option value="">Select borrower</option>{borrowers.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</Select></Field>}<Field label="Description"><Input required value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })}/></Field><div className="grid gap-3 sm:grid-cols-2"><Field label="Collateral type"><Input required placeholder="e.g. Motorcycle" value={form.collateralType} onChange={(e) => setForm({ ...form, collateralType: e.target.value })}/></Field><Field label="Estimated value (TZS)"><Input required type="number" min="1" value={form.estimatedValue} onChange={(e) => setForm({ ...form, estimatedValue: e.target.value })}/></Field></div><Field label="Document reference"><Input value={form.documentReference} onChange={(e) => setForm({ ...form, documentReference: e.target.value })}/></Field><div className="flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Cancel</Button><Button type="submit" disabled={busy}>Save collateral</Button></div></form></Modal>; }
function ApplicationDialog({ open, onClose, mutation, borrowers, products, groups, busy }) { const [form, setForm] = useState({ borrowerId: "", productId: "", principal: "", termMonths: "", repaymentFrequency: "monthly", intendedUse: "", groupId: "" }); const selectedProduct = products.find((item) => item.id === form.productId); const submit = (event) => { event.preventDefault(); mutation.mutate({ ...form, principal: Number(form.principal), termMonths: Number(form.termMonths), groupId: form.groupId || null, guarantorIds: [], collateralIds: [] }); }; return <Modal open={open} title="Submit loan application" description="The server validates product limits and borrower identity status before placing it in the decision queue." onClose={onClose}><form onSubmit={submit} className="space-y-4"><InlineError error={mutation.error?.message}/><div className="grid gap-3 sm:grid-cols-2"><Field label="Borrower"><Select required value={form.borrowerId} onChange={(e) => setForm({ ...form, borrowerId: e.target.value })}><option value="">Select borrower</option>{borrowers.map((item) => <option key={item.id} value={item.id}>{item.name} · {item.kycStatus}</option>)}</Select></Field><Field label="Loan product"><Select required value={form.productId} onChange={(e) => setForm({ ...form, productId: e.target.value, repaymentFrequency: products.find((item) => item.id === e.target.value)?.repaymentFrequency || "monthly" })}><option value="">Select product</option>{products.filter((item) => item.status === "Active").map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</Select></Field><Field label="Principal requested (TZS)" hint={selectedProduct ? `${currency.format(selectedProduct.minimumPrincipal)} – ${currency.format(selectedProduct.maximumPrincipal)}` : "Select a product to view limits"}><Input required type="number" min="1" value={form.principal} onChange={(e) => setForm({ ...form, principal: e.target.value })}/></Field><Field label="Term (months)"><Input required type="number" min="1" value={form.termMonths} onChange={(e) => setForm({ ...form, termMonths: e.target.value })}/></Field><Field label="Repayment frequency"><Select value={form.repaymentFrequency} onChange={(e) => setForm({ ...form, repaymentFrequency: e.target.value })}><option value="weekly">Weekly</option><option value="biweekly">Biweekly</option><option value="monthly">Monthly</option></Select></Field><Field label="Borrower group"><Select value={form.groupId} onChange={(e) => setForm({ ...form, groupId: e.target.value })}><option value="">Individual borrower</option>{groups.map((group) => <option key={group.id} value={group.id}>{group.name}</option>)}</Select></Field></div><Field label="Intended use"><textarea required minLength={3} value={form.intendedUse} onChange={(e) => setForm({ ...form, intendedUse: e.target.value })} className="mt-1.5 min-h-24 w-full rounded-xl border border-slate-300 p-3 text-sm outline-none focus:border-emerald-600 focus:ring-2 focus:ring-emerald-100"/></Field><div className="rounded-xl bg-amber-50 p-3 text-xs text-amber-800">Guarantor and collateral records can be added from the borrower register. Product security rules are enforced by the server before submission.</div><div className="flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Cancel</Button><Button type="submit" disabled={busy}>Submit for review</Button></div></form></Modal>; }
function DecisionDialog({ application, onClose, mutation, busy }) { const [decision, setDecision] = useState("Approved"); const [amount, setAmount] = useState(""); const [note, setNote] = useState(""); if (!application || application.status !== "Submitted") return null; const submit = (event) => { event.preventDefault(); mutation.mutate({ applicationId: application.id, decision, approvedAmount: decision === "Approved" ? Number(amount) : 0, decisionNote: note }); }; return <Modal open={Boolean(application)} title="Credit decision" description={`${application.borrowerName} · requested ${currency.format(application.amount)}`} onClose={onClose}><form onSubmit={submit} className="space-y-4"><InlineError error={mutation.error?.message}/><Field label="Decision"><Select value={decision} onChange={(e) => setDecision(e.target.value)}><option>Approved</option><option>Rejected</option></Select></Field>{decision === "Approved" && <Field label="Approved amount (TZS)"><Input required type="number" min="1" max={application.amount} value={amount} onChange={(e) => setAmount(e.target.value)}/></Field>}<Field label="Decision note"><textarea value={note} onChange={(e) => setNote(e.target.value)} className="mt-1.5 min-h-24 w-full rounded-xl border border-slate-300 p-3 text-sm outline-none focus:border-emerald-600 focus:ring-2 focus:ring-emerald-100"/></Field><div className="flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Cancel</Button><Button type="submit" variant={decision === "Rejected" ? "danger" : "primary"} disabled={busy}>{decision === "Approved" ? "Approve application" : "Reject application"}</Button></div></form></Modal>; }
function DisbursementDialog({ application, onClose, mutation, sessions, busy }) { const [form, setForm] = useState({ disbursedOn: tzToday(), paymentMethod: "cash", provider: "", providerReference: "", cashSessionId: "" }); if (!application || application.status !== "Approved") return null; const submit = (event) => { event.preventDefault(); mutation.mutate({ applicationId: application.id, ...form, cashSessionId: form.paymentMethod === "cash" ? form.cashSessionId || null : null }); }; const cashSessions = sessions.filter((item) => item.status === "Open"); return <Modal open={Boolean(application)} title="Disburse approved loan" description={`${application.borrowerName} · approved ${currency.format(application.approvedAmount)}`} onClose={onClose}><form onSubmit={submit} className="space-y-4"><InlineError error={mutation.error?.message}/><div className="grid gap-3 sm:grid-cols-2"><Field label="Disbursement date"><Input required type="date" value={form.disbursedOn} onChange={(e) => setForm({ ...form, disbursedOn: e.target.value })}/></Field><Field label="Channel"><Select value={form.paymentMethod} onChange={(e) => setForm({ ...form, paymentMethod: e.target.value })}><option value="cash">Cash</option><option value="mobile_money">Mobile money</option><option value="bank_transfer">Bank transfer</option></Select></Field>{form.paymentMethod === "cash" ? <Field label="Open cash session"><Select required value={form.cashSessionId} onChange={(e) => setForm({ ...form, cashSessionId: e.target.value })}><option value="">Select open cash session</option>{cashSessions.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</Select></Field> : <><Field label="Provider"><Input placeholder="e.g. M-Pesa, Airtel Money" value={form.provider} onChange={(e) => setForm({ ...form, provider: e.target.value })}/></Field><Field label="Provider reference"><Input value={form.providerReference} onChange={(e) => setForm({ ...form, providerReference: e.target.value })}/></Field></>}</div>{form.paymentMethod === "mobile_money" && <div className="rounded-xl bg-amber-50 p-3 text-xs text-amber-800">A mobile-money receipt reference can be recorded. Live provider dispatch remains disabled until approved server-side credentials are configured.</div>}<div className="flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Cancel</Button><Button type="submit" disabled={busy || (form.paymentMethod === "cash" && !cashSessions.length)}><Banknote size={15}/>Disburse and create schedule</Button></div></form></Modal>; }
function RepaymentDialog({ loan, onClose, mutation, sessions, busy }) { const [form, setForm] = useState({ amount: "", receivedOn: tzToday(), paymentMethod: "cash", provider: "", providerReference: "", cashSessionId: "" }); if (!loan) return null; const submit = (event) => { event.preventDefault(); mutation.mutate({ loanId: loan.id, amount: Number(form.amount), receivedOn: form.receivedOn, paymentMethod: form.paymentMethod, provider: form.provider, providerReference: form.providerReference, cashSessionId: form.paymentMethod === "cash" ? form.cashSessionId || null : null }); }; const sessionsOpen = sessions.filter((item) => item.status === "Open"); return <Modal open={Boolean(loan)} title="Record repayment" description={`${loan.borrowerName} · outstanding ${currency.format(loan.outstanding)}`} onClose={onClose}><form onSubmit={submit} className="space-y-4"><InlineError error={mutation.error?.message}/><div className="grid gap-3 sm:grid-cols-2"><Field label="Amount received (TZS)"><Input required type="number" min="1" max={loan.outstanding} value={form.amount} onChange={(e) => setForm({ ...form, amount: e.target.value })}/></Field><Field label="Received date"><Input required type="date" value={form.receivedOn} onChange={(e) => setForm({ ...form, receivedOn: e.target.value })}/></Field><Field label="Channel"><Select value={form.paymentMethod} onChange={(e) => setForm({ ...form, paymentMethod: e.target.value })}><option value="cash">Cash</option><option value="mobile_money">Mobile money</option><option value="bank_transfer">Bank transfer</option></Select></Field>{form.paymentMethod === "cash" ? <Field label="Open cash session"><Select required value={form.cashSessionId} onChange={(e) => setForm({ ...form, cashSessionId: e.target.value })}><option value="">Select open cash session</option>{sessionsOpen.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</Select></Field> : <><Field label="Provider"><Input value={form.provider} onChange={(e) => setForm({ ...form, provider: e.target.value })}/></Field><Field label="Provider reference"><Input value={form.providerReference} onChange={(e) => setForm({ ...form, providerReference: e.target.value })}/></Field></>}</div><div className="rounded-xl bg-slate-50 p-3 text-xs text-slate-600">A server-issued receipt number, idempotency control, allocation across installments, audit log, and cash transaction are created together.</div><div className="flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Cancel</Button><Button type="submit" disabled={busy || (form.paymentMethod === "cash" && !sessionsOpen.length)}><ReceiptText size={15}/>Post repayment</Button></div></form></Modal>; }
function SavingsDialog({ open, onClose, mutation, borrowers, sessions, busy }) { const [form, setForm] = useState({ borrowerId: "", amount: "", transactionType: "Deposit", transactedOn: tzToday(), paymentMethod: "cash", providerReference: "", cashSessionId: "", note: "" }); const submit = (event) => { event.preventDefault(); mutation.mutate({ ...form, amount: Number(form.amount), cashSessionId: form.paymentMethod === "cash" ? form.cashSessionId || null : null }); }; const sessionsOpen = sessions.filter((item) => item.status === "Open"); return <Modal open={open} title="Savings transaction" description="Deposits and withdrawals are posted only after borrower-balance validation." onClose={onClose}><form onSubmit={submit} className="space-y-3"><InlineError error={mutation.error?.message}/><div className="grid gap-3 sm:grid-cols-2"><Field label="Borrower"><Select required value={form.borrowerId} onChange={(e) => setForm({ ...form, borrowerId: e.target.value })}><option value="">Select borrower</option>{borrowers.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</Select></Field><Field label="Transaction"><Select value={form.transactionType} onChange={(e) => setForm({ ...form, transactionType: e.target.value })}><option>Deposit</option><option>Withdrawal</option></Select></Field><Field label="Amount (TZS)"><Input required type="number" min="1" value={form.amount} onChange={(e) => setForm({ ...form, amount: e.target.value })}/></Field><Field label="Date"><Input required type="date" value={form.transactedOn} onChange={(e) => setForm({ ...form, transactedOn: e.target.value })}/></Field><Field label="Channel"><Select value={form.paymentMethod} onChange={(e) => setForm({ ...form, paymentMethod: e.target.value })}><option value="cash">Cash</option><option value="mobile_money">Mobile money</option><option value="bank_transfer">Bank transfer</option></Select></Field>{form.paymentMethod === "cash" ? <Field label="Open cash session"><Select required value={form.cashSessionId} onChange={(e) => setForm({ ...form, cashSessionId: e.target.value })}><option value="">Select open cash session</option>{sessionsOpen.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</Select></Field> : <Field label="Provider reference"><Input value={form.providerReference} onChange={(e) => setForm({ ...form, providerReference: e.target.value })}/></Field>}</div><Field label="Internal note"><Input value={form.note} onChange={(e) => setForm({ ...form, note: e.target.value })}/></Field><div className="flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Cancel</Button><Button type="submit" disabled={busy || (form.paymentMethod === "cash" && !sessionsOpen.length)}>Post transaction</Button></div></form></Modal>; }
function CashOpenDialog({ open, onClose, mutation, busy }) { const [form, setForm] = useState({ openingBalance: "", openedOn: tzToday(), note: "" }); const submit = (event) => { event.preventDefault(); mutation.mutate({ ...form, openingBalance: Number(form.openingBalance || 0) }); }; return <Modal open={open} title="Open cash session" description="A teller session is required before cash loan, repayment, or savings postings." onClose={onClose}><form onSubmit={submit} className="space-y-4"><InlineError error={mutation.error?.message}/><Field label="Opening float (TZS)"><Input required type="number" min="0" value={form.openingBalance} onChange={(e) => setForm({ ...form, openingBalance: e.target.value })}/></Field><Field label="Opening date"><Input required type="date" value={form.openedOn} onChange={(e) => setForm({ ...form, openedOn: e.target.value })}/></Field><Field label="Note"><Input value={form.note} onChange={(e) => setForm({ ...form, note: e.target.value })}/></Field><div className="flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Cancel</Button><Button type="submit" disabled={busy}>Open session</Button></div></form></Modal>; }
function CashCloseDialog({ session, onClose, mutation, busy }) { const [form, setForm] = useState({ closingBalance: "", note: "" }); if (!session) return null; const submit = (event) => { event.preventDefault(); mutation.mutate({ cashSessionId: session.id, closingBalance: Number(form.closingBalance), note: form.note }); }; return <Modal open={Boolean(session)} title="Close cash session" description="The server calculates expected cash from the session’s posted inflows and outflows." onClose={onClose}><form onSubmit={submit} className="space-y-4"><InlineError error={mutation.error?.message}/><div className="rounded-xl bg-slate-50 p-3 text-sm text-slate-700">Opening float: <strong>{currency.format(session.openingBalance)}</strong></div><Field label="Counted closing cash (TZS)"><Input required type="number" min="0" value={form.closingBalance} onChange={(e) => setForm({ ...form, closingBalance: e.target.value })}/></Field><Field label="Reconciliation note"><Input value={form.note} onChange={(e) => setForm({ ...form, note: e.target.value })}/></Field><div className="flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Cancel</Button><Button type="submit" disabled={busy}>Close and reconcile</Button></div></form></Modal>; }
function CollectionDialog({ loan, onClose, mutation, busy }) { const [form, setForm] = useState({ action: "Call", dueOn: tzToday(), note: "" }); if (!loan) return null; const submit = (event) => { event.preventDefault(); mutation.mutate({ loanId: loan.id, ...form }); }; return <Modal open={Boolean(loan)} title="Assign collection action" description={`${loan.borrowerName} · ${currency.format(loan.outstanding)} outstanding`} onClose={onClose}><form onSubmit={submit} className="space-y-4"><InlineError error={mutation.error?.message}/><Field label="Action"><Select value={form.action} onChange={(e) => setForm({ ...form, action: e.target.value })}><option>Call</option><option>Visit</option><option>Promise to pay</option><option>Restructure review</option></Select></Field><Field label="Follow-up due"><Input required type="date" value={form.dueOn} onChange={(e) => setForm({ ...form, dueOn: e.target.value })}/></Field><Field label="Collection note"><textarea value={form.note} onChange={(e) => setForm({ ...form, note: e.target.value })} className="mt-1.5 min-h-24 w-full rounded-xl border border-slate-300 p-3 text-sm outline-none focus:border-emerald-600 focus:ring-2 focus:ring-emerald-100"/></Field><div className="flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Cancel</Button><Button type="submit" disabled={busy}>Assign action</Button></div></form></Modal>; }
